SELECT *
FROM shopwizard.tShpShipCheck

    AND ShipCheckNo = #{pShipCheckNo}
    AND ShopCode = #{pShopCode}
    AND ShipCheckDesc = #{pShipCheckDesc}
    AND ShipCheckDate = #{pShipCheckDate}


        AND (
            ShipCheckDate >= DATE_FORMAT(#{pStartDate}, '%Y-%m-%d') AND
            ShipCheckDate <  ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y-%m-%d'), INTERVAL 1 DAY)
        )




    LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tShpShipCheck

    AND ShipCheckNo = #{pShipCheckNo}
